import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> result = new ArrayList<>();
        int wordLength = words[0].length();
        int totalLength = wordLength * words.length;
        if (totalLength > s.length()) return result;
        Map<String, Integer> required = new HashMap<>();
        for (String word : words) required.put(word, required.getOrDefault(word, 0) + 1);
        for (int start = 0; start + totalLength <= s.length(); start++) {
            Map<String, Integer> found = new HashMap<>();
            int count = 0;
            while (count < words.length) {
                int offset = start + count * wordLength;
                String chunk = s.substring(offset, offset + wordLength);
                if (!required.containsKey(chunk)) break;
                found.put(chunk, found.getOrDefault(chunk, 0) + 1);
                if (found.get(chunk) > required.get(chunk)) break;
                count++;
            }
            if (count == words.length) result.add(start);
        }
        return result;
    }
}

