import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> result = new ArrayList<>();
        int wordLength = words[0].length();
        int wordCount = words.length;
        int totalLength = wordLength * wordCount;
        if (totalLength > s.length()) return result;
        Map<String, Integer> required = new HashMap<>();
        for (String word : words) required.put(word, required.getOrDefault(word, 0) + 1);
        for (int alignment = 0; alignment < wordLength; alignment++) {
            int left = alignment;
            int used = 0;
            Map<String, Integer> window = new HashMap<>();
            for (int right = alignment; right + wordLength <= s.length(); right += wordLength) {
                String chunk = s.substring(right, right + wordLength);
                if (!required.containsKey(chunk)) {
                    window.clear();
                    used = 0;
                    left = right + wordLength;
                    continue;
                }
                window.put(chunk, window.getOrDefault(chunk, 0) + 1);
                used++;
                while (window.get(chunk) > required.get(chunk)) {
                    String removed = s.substring(left, left + wordLength);
                    window.put(removed, window.get(removed) - 1);
                    left += wordLength;
                    used--;
                }
                if (used == wordCount) {
                    result.add(left);
                    String removed = s.substring(left, left + wordLength);
                    window.put(removed, window.get(removed) - 1);
                    left += wordLength;
                    used--;
                }
            }
        }
        return result;
    }
}
